-- PT117-S2-Q10. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT117-S2-Q10$batch03$ AND q.stimulus=$batch03$Before their larvae hatch, each parental pair of Nicrophorus beetles buries the carcass of a small vertebrate nearby. For several days after the larvae hatch, both beetles feed their voracious larvae from the carcass, which is entirely consumed within a week. Since both parents help with feeding, larvae should benefit from both parents’ presence; however, removing one parent before the hatching results in larvae that grow both larger and heavier than they otherwise would be.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, best helps to explain why removing one parent resulted in larger, heavier larvae?$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT117-S2-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT117-S2-Q10$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S2-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT117-S2-Q10$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Both parents feed the larvae, which should help them.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Removing one parent produces larger, heavier larvae?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The carcass is a fixed amount of food, all eaten within a week. If the parents eat from it too, each parent takes food away from the larvae. One fewer parent leaves more for the young.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a way the second parent reduces the larvae's food.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT117-S2-Q10$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$If two beetles bury a larger carcass, two parents would mean *more* food. That makes the result stranger.$batch03$), ($batch03$B$batch03$, $batch03$Parents eat from the carcass themselves. With one parent gone, more of the fixed food supply goes to the larvae, so they grow larger.$batch03$), ($batch03$C$batch03$, $batch03$Taking turns describes how parents share work. It does not explain bigger larvae with only one parent.$batch03$), ($batch03$D$batch03$, $batch03$Larvae finding food after a week would be true whether one or two parents are present.$batch03$), ($batch03$E$batch03$, $batch03$Two parents defending the carcass better would favor two parents, which deepens the puzzle.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT117-S2-Q10$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
